import{_ as e,o as r,c as d,a3 as a}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"FreeLLM 目錄","description":"awesome-freellm-apis / freellm.net 免費 LLM API 彙總：提供商目錄、Base URL、與 MiniTavern 填法及本手冊專頁互鏈。","frontmatter":{"title":"FreeLLM 目錄","description":"awesome-freellm-apis / freellm.net 免費 LLM API 彙總：提供商目錄、Base URL、與 MiniTavern 填法及本手冊專頁互鏈。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"FreeLLM 目錄 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"awesome-freellm-apis / freellm.net 免費 LLM API 彙總：提供商目錄、Base URL、與 MiniTavern 填法及本手冊專頁互鏈。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/freellm"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/freellm"}]]},"headers":[],"relativePath":"zh-TW/free-cloud/freellm.md","filePath":"zh-TW/free-cloud/freellm.md","lastUpdated":1787224147000}'),o={name:"zh-TW/free-cloud/freellm.md"};function l(n,t,i,s,h,p){return r(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="freellm-目錄" tabindex="-1">FreeLLM 目錄 <a class="header-anchor" href="#freellm-目錄" aria-label="Permalink to &quot;FreeLLM 目錄&quot;">​</a></h1><p>社區維護的<strong>免費 LLM API 目錄</strong>：<a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">awesome-freellm-apis</a>（數據每日自 <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> 刷新）。收錄數十家提供商、數百個免費模型，並標註是否要信用卡、手機驗證，以及 Base URL / 拿 Key 鏈接。</p><p>本頁是 <strong>MiniTavern 用戶向摘要</strong>：怎麼用該目錄選廠商，以及和本手冊已有專頁、總覽的對應關係。<strong>模型 ID、限速、是否仍免費以 freellm.net / 各廠商控制台為準</strong>（倉庫 README 會註明最近更新日期）。</p><h2 id="官網與入口" tabindex="-1">官網與入口 <a class="header-anchor" href="#官網與入口" aria-label="Permalink to &quot;官網與入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資源</th><th>地址</th></tr></thead><tbody><tr><td>GitHub 倉庫</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">open-free-llm-api/awesome-freellm-apis</a></td></tr><tr><td>中文 README</td><td><a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">README.zh-CN.md</a></td></tr><tr><td>在線站</td><td><a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>（瀏覽 · Playground · 配置生成器）</td></tr><tr><td>API Key 目錄</td><td><a href="https://freellm.net/free-llm-api-keys/" target="_blank" rel="noreferrer">freellm.net/free-llm-api-keys</a></td></tr><tr><td>模型對比</td><td><a href="https://freellm.net/compare/" target="_blank" rel="noreferrer">freellm.net/compare</a></td></tr></tbody></table><h2 id="怎麼用-對接-minitavern" tabindex="-1">怎麼用（對接 MiniTavern） <a class="header-anchor" href="#怎麼用-對接-minitavern" aria-label="Permalink to &quot;怎麼用（對接 MiniTavern）&quot;">​</a></h2><ol><li>在 <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a> 或倉庫「提供商目錄」裡挑一家：<strong>優先免信用卡</strong>（如 Groq、Gemini、智譜 Flash）。</li><li>點提供商的 <strong>Get Key</strong>，註冊並複製 API Key。</li><li>記下 <strong>Base URL</strong> 與 <strong>Model ID</strong>（倉庫 Quick Reference / Best Models 表）。</li><li>打開 MiniTavern：<strong>設置 → 模型 → 模型連接 → 新建</strong><ul><li>若本手冊已有專頁 / App 預設（見下表）→ 按專頁填。</li><li>否則選 <strong>自定義 (OpenAI)</strong>，粘貼 Base URL + Key + 模型 ID → <strong>測試</strong>。</li></ul></li></ol><p>通用步驟見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a>。角色扮演優先選<strong>對話向</strong>文本模型；編碼 Agent 模型未必適合長劇情。</p><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>收錄標準（官方）</td><td>明確免費層（不止短期試用）、公開可訪問、試用金需標明</td></tr><tr><td>數據時效</td><td>每日自動更新；限速與名單會變</td></tr><tr><td>與本手冊關係</td><td>總覽與專頁寫「怎麼在 App 裡填」；本頁 + freellm.net 寫「還有哪些廠商可試」</td></tr></tbody></table><h2 id="本手冊已有專頁-優先讀" tabindex="-1">本手冊已有專頁（優先讀） <a class="header-anchor" href="#本手冊已有專頁-優先讀" aria-label="Permalink to &quot;本手冊已有專頁（優先讀）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提供商</th><th>手冊</th><th>App 平臺</th></tr></thead><tbody><tr><td>Agnes AI</td><td><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a></td><td>自定義 (OpenAI) / Images</td></tr><tr><td>OpenCode Zen</td><td><a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">OpenCode Zen</a></td><td>自定義 (OpenAI)</td></tr><tr><td>AIHubMix</td><td><a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a></td><td>自定義 (OpenAI) / Images</td></tr><tr><td>OpenRouter</td><td><a href="/ultra_guides/zh-TW/free-cloud/openrouter">OpenRouter</a></td><td>OpenRouter</td></tr><tr><td>智譜 / 硅基 / 百鍊 / DeepSeek / Gemini / Groq 等</td><td><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端總覽</a></td><td>見總覽各節</td></tr></tbody></table><h2 id="提供商目錄-永久免費層-·-摘要" tabindex="-1">提供商目錄（永久免費層 · 摘要） <a class="header-anchor" href="#提供商目錄-永久免費層-·-摘要" aria-label="Permalink to &quot;提供商目錄（永久免費層 · 摘要）&quot;">​</a></h2><p>下列摘自倉庫「Permanent Free Tiers」（約 2026-08-20）。<strong>免費模型數量會變</strong>；完整表見 <a href="https://github.com/open-free-llm-api/awesome-freellm-apis" target="_blank" rel="noreferrer">GitHub</a> / <a href="https://freellm.net" target="_blank" rel="noreferrer">freellm.net</a>。</p><table tabindex="0"><thead><tr><th>提供商</th><th>約免費模型數</th><th>信用卡等</th><th>能力概覽</th><th>Key</th></tr></thead><tbody><tr><td>NVIDIA NIM</td><td>125</td><td>手機驗證</td><td>文本 / 圖 / 視頻 / 視覺等</td><td><a href="https://build.nvidia.com/settings/api-keys" target="_blank" rel="noreferrer">build.nvidia.com</a></td></tr><tr><td>ModelScope（魔搭）</td><td>56</td><td>註冊</td><td>文本 / 圖 / 視頻 / 視覺</td><td><a href="https://modelscope.cn/my/myaccesstoken" target="_blank" rel="noreferrer">modelscope.cn</a></td></tr><tr><td>Cloudflare Workers AI</td><td>40</td><td>否</td><td>文本 / 圖 / 代碼等</td><td><a href="https://dash.cloudflare.com/profile/api-tokens" target="_blank" rel="noreferrer">dash.cloudflare.com</a></td></tr><tr><td>Google Gemini</td><td>17</td><td>否</td><td>文本 / 多模態</td><td><a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>GitHub Models</td><td>16</td><td>否</td><td>文本等</td><td><a href="https://github.com/marketplace/models" target="_blank" rel="noreferrer">GitHub Models</a></td></tr><tr><td>LLM7.io</td><td>16</td><td>否</td><td>文本 / 多模態</td><td><a href="https://token.llm7.io" target="_blank" rel="noreferrer">token.llm7.io</a></td></tr><tr><td>OVHcloud AI Endpoints</td><td>14</td><td>註冊</td><td>文本等</td><td><a href="https://www.ovhcloud.com/en/public-cloud/ai-endpoints/catalog/" target="_blank" rel="noreferrer">ovhcloud.com</a></td></tr><tr><td>Ollama Cloud</td><td>13</td><td>註冊</td><td>文本 / 視覺等</td><td><a href="https://ollama.com/settings/keys" target="_blank" rel="noreferrer">ollama.com/settings/keys</a></td></tr><tr><td>Groq</td><td>12</td><td>否</td><td>文本</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com/keys</a></td></tr><tr><td>Mistral AI</td><td>12</td><td>否</td><td>文本</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Cohere</td><td>12</td><td>否</td><td>文本</td><td><a href="https://dashboard.cohere.com/api-keys" target="_blank" rel="noreferrer">dashboard.cohere.com</a></td></tr><tr><td>Kilo Code</td><td>12</td><td>否</td><td>文本等</td><td><a href="https://kilo.ai" target="_blank" rel="noreferrer">kilo.ai</a></td></tr><tr><td>OpenCode Zen</td><td>11</td><td>註冊</td><td>見 <a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">專頁</a></td><td><a href="https://opencode.ai/auth" target="_blank" rel="noreferrer">opencode.ai/auth</a></td></tr><tr><td>Cerebras</td><td>8</td><td>否</td><td>文本</td><td><a href="https://cloud.cerebras.ai/" target="_blank" rel="noreferrer">cloud.cerebras.ai</a></td></tr><tr><td>Aion Labs</td><td>7</td><td>註冊</td><td>文本（含 RP 向）</td><td><a href="https://www.aionlabs.ai" target="_blank" rel="noreferrer">aionlabs.ai</a></td></tr><tr><td>Hugging Face</td><td>7</td><td>否</td><td>文本 / 代碼</td><td><a href="https://huggingface.co/settings/tokens" target="_blank" rel="noreferrer">huggingface.co/settings/tokens</a></td></tr><tr><td>Agnes AI</td><td>5</td><td>註冊</td><td>見 <a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">專頁</a></td><td><a href="https://platform.agnes-ai.com/settings/apiKeys" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>阿里雲百鍊（國際站等）</td><td>5</td><td>註冊</td><td>見總覽 <a href="/ultra_guides/zh-TW/free-cloud/#通義千問--阿里雲百鍊">通義</a></td><td><a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">百鍊控制台</a></td></tr><tr><td>智譜 Z AI</td><td>4</td><td>否</td><td>見總覽 <a href="/ultra_guides/zh-TW/free-cloud/#智譜-ai-glm">智譜</a></td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>SambaNova</td><td>4</td><td>註冊</td><td>文本</td><td><a href="https://cloud.sambanova.ai/apis" target="_blank" rel="noreferrer">cloud.sambanova.ai</a></td></tr><tr><td>硅基流動</td><td>3</td><td>註冊</td><td>見總覽 <a href="/ultra_guides/zh-TW/free-cloud/#硅基流動-siliconflow">硅基</a></td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>xAI / Grok</td><td>3</td><td>註冊</td><td>文本（常為贈金）</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>DeepSeek</td><td>2</td><td>註冊</td><td>見總覽 <a href="/ultra_guides/zh-TW/free-cloud/#deepseek">DeepSeek</a></td><td><a href="https://platform.deepseek.com" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>其它（Chutes、Glhf、AI21、Nscale、Nebius 等）</td><td>少</td><td>多為註冊</td><td>以 freellm 為準</td><td>見倉庫 Quick Reference</td></tr></tbody></table><h3 id="可再生免費額度" tabindex="-1">可再生免費額度 <a class="header-anchor" href="#可再生免費額度" aria-label="Permalink to &quot;可再生免費額度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>提供商</th><th>說明</th><th>手冊</th></tr></thead><tbody><tr><td>OpenRouter</td><td><code>:free</code> 池；充值約 $10+ 可提高免費日請求上限</td><td><a href="/ultra_guides/zh-TW/free-cloud/openrouter">OpenRouter</a></td></tr></tbody></table><h2 id="快速參考-·-base-url-與-app" tabindex="-1">快速參考 · Base URL 與 App <a class="header-anchor" href="#快速參考-·-base-url-與-app" aria-label="Permalink to &quot;快速參考 · Base URL 與 App&quot;">​</a></h2><p>多數廠商可走 <strong>自定義 (OpenAI)</strong>。Gemini 請用 App 預設 <strong>Gemini(Google)</strong>，勿硬套 OpenAI Base URL。</p><table tabindex="0"><thead><tr><th>提供商</th><th>Base URL（常見）</th><th>App</th></tr></thead><tbody><tr><td>Groq</td><td><code>https://api.groq.com/openai/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>硅基流動</td><td><code>https://api.siliconflow.cn/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>智譜</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td><td>自定義 (OpenAI)</td></tr><tr><td>Agnes AI</td><td><code>https://apihub.agnes-ai.com/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>OpenCode Zen</td><td><code>https://opencode.ai/zen/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>OpenRouter</td><td><code>https://openrouter.ai/api/v1</code></td><td><strong>OpenRouter</strong></td></tr><tr><td>NVIDIA NIM</td><td><code>https://integrate.api.nvidia.com/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>ModelScope</td><td><code>https://api-inference.modelscope.cn/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>GitHub Models</td><td><code>https://models.github.ai/inference</code></td><td>自定義 (OpenAI)</td></tr><tr><td>Cerebras</td><td><code>https://api.cerebras.ai/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>SambaNova</td><td><code>https://api.sambanova.ai/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>Mistral</td><td><code>https://api.mistral.ai/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>Hugging Face</td><td><code>https://router.huggingface.co/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>LLM7.io</td><td><code>https://api.llm7.io/v1</code></td><td>自定義 (OpenAI)</td></tr><tr><td>Ollama Cloud</td><td><code>https://api.ollama.com</code>（以文檔為準）</td><td>自定義 (OpenAI)</td></tr><tr><td>Gemini</td><td>預設即可</td><td><strong>Gemini(Google)</strong></td></tr><tr><td>DeepSeek</td><td>預設即可</td><td><strong>DeepSeek</strong></td></tr><tr><td>通義 / 百鍊</td><td>預設即可</td><td><strong>Qwen</strong></td></tr></tbody></table><p>Cloudflare Workers AI 路徑含 <code>{account_id}</code>，配置較特殊；不熟悉時可先選 Groq / 智譜 / OpenRouter。</p><p>完整 Key 鏈接與「各廠最佳免費模型」長表見倉庫 <a href="https://github.com/open-free-llm-api/awesome-freellm-apis/blob/main/README.zh-CN.md" target="_blank" rel="noreferrer">Best Free Models</a>。</p><h2 id="熱門免費模型-倉庫周用量示例" tabindex="-1">熱門免費模型（倉庫周用量示例） <a class="header-anchor" href="#熱門免費模型-倉庫周用量示例" aria-label="Permalink to &quot;熱門免費模型（倉庫周用量示例）&quot;">​</a></h2><p>僅作「近期有人用」參考，<strong>不等於</strong>最適合角色扮演：</p><table tabindex="0"><thead><tr><th>方向</th><th>示例（以 freellm / 廣場 ID 為準）</th></tr></thead><tbody><tr><td>聚合免費池</td><td>OpenRouter：<code>nvidia/nemotron-3-ultra-550b-a55b:free</code> 等</td></tr><tr><td>高速推理</td><td>Groq：<code>llama-3.3-70b-versatile</code>、<code>moonshotai/kimi-k2-instruct</code></td></tr><tr><td>中文對話</td><td>智譜 Flash、硅基免費標籤模型、百鍊新人額度</td></tr><tr><td>多模態文本+生圖</td><td><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a>、<a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a></td></tr></tbody></table><h2 id="圖片-視頻" tabindex="-1">圖片 / 視頻 <a class="header-anchor" href="#圖片-視頻" aria-label="Permalink to &quot;圖片 / 視頻&quot;">​</a></h2><ul><li>目錄裡多家標有 <code>image</code> / <code>video</code> modality；<strong>MiniTavern 生圖</strong>需 OpenAI Images 兼容或 App 已支持的平臺（見 <a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費生圖</a>）。</li><li>App <strong>無內置視頻生成</strong>；視頻模型僅對照官網能力。</li></ul><h2 id="相關章節" tabindex="-1">相關章節 <a class="header-anchor" href="#相關章節" aria-label="Permalink to &quot;相關章節&quot;">​</a></h2><ul><li><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端總覽</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a> · <a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">OpenCode Zen</a> · <a href="/ultra_guides/zh-TW/free-cloud/aihubmix">AIHubMix</a> · <a href="/ultra_guides/zh-TW/free-cloud/openrouter">OpenRouter</a></li><li><a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a></li><li><a href="/ultra_guides/zh-TW/manual/errors">錯誤排錯</a></li></ul>',28)])])}const u=e(o,[["render",l]]);export{f as __pageData,u as default};
